// src/App.js
import './Style/App.css';
import DisplayAllTasks from './components/DisplayAllTasks';
import TasksInputForm from './components/TasksInputForm';
import TaskCalendar from './components/TaskCalendar';

function App() {
  return (
    <div className="App">
      <div className='components'>

      <TaskCalendar/>  
      <TasksInputForm/>
      <DisplayAllTasks/>
      </div>
    </div>
  );
}

export default App;
